        const ends2 = [-1, 1].map((k) => new Part_(a, T3, CAB.hw, k * (CAB.hl - T3), 0, 0, 1, H));
        this.sides = [-1, 1].map((k) => new Part_(a, CAB.hl, T3, 0, k * (CAB.hw - T3), 0, 1, H));
