          parts.push([box9(len - 0.4, 0.06, 0.25), "#e4d27a", mid, st.deck + 0.03, LANE - CAB.hw - 0.35]);
          parts.push([box9(len - 0.4, 0.06, 0.25), "#e4d27a", mid, st.deck + 0.03, -LANE - CAB.hw - 0.35]);
          parts.push([box9(len - 0.4, 0.06, 0.25), "#e4d27a", mid, st.deck + 0.03, LANE + CAB.hw + 0.35]);
